/* smart=1 preview: Smart Glow, Smart Countdown, Smart Alert (bell), Smart Goal */
(function(){
  if(/[?&]smart=0\b/.test(location.search))return;
  var D8=function(e){return String(e).replace(/[0-9]/g,function(d){return "٠١٢٣٤٥٦٧٨٩"[+d]})};
  var reduce=!!(window.matchMedia&&matchMedia("(prefers-reduced-motion: reduce)").matches);
  var alerts={};try{alerts=JSON.parse(localStorage.getItem("ks_alert")||"{}")||{}}catch(e){alerts={}}
  var save=function(){try{localStorage.setItem("ks_alert",JSON.stringify(alerts))}catch(e){}};
  var prev={},seen={};
  function rows(){return [].slice.call(document.querySelectorAll(".match-row[data-k]"))}
  function beep(){ if(reduce)return; try{var C=window.AudioContext||window.webkitAudioContext;if(!C)return;var a=new C();var o=a.createOscillator(),g=a.createGain();o.type="sine";o.frequency.value=680;g.gain.value=.07;o.connect(g);g.connect(a.destination);o.start();setTimeout(function(){try{o.stop();a.close()}catch(e){}},300)}catch(e){} }
  function goal(row,side){
    if(!row)return;
    row.classList.remove("ks-goal-h","ks-goal-a");
    row.classList.add(side==="h"?"ks-goal-h":"ks-goal-a");
    var w=row;
    var old=w.querySelector(".ks-goal-word");if(old&&old.parentNode)old.parentNode.removeChild(old);
    var g=document.createElement("span");g.className="ks-goal-word";g.textContent="GOAL";
    w.appendChild(g);
    beep();
    setTimeout(function(){row.classList.remove("ks-goal-h","ks-goal-a");if(g.parentNode)g.parentNode.removeChild(g)},4200);
  }
  function notify(txt){
    if(!("Notification" in window)||Notification.permission!=="granted")return;
    try{new Notification("كورهسطين",{body:txt})}catch(e){}
  }
  function check(){
    rows().forEach(function(r){
      var k=r.dataset.k,h=r.dataset.hs,a=r.dataset.as;
      if(h===""&&a==="")return;
      var p=prev[k];
      var nh=parseInt(h,10),na=parseInt(a,10),ph=p?parseInt(p.h,10):NaN,pa=p?parseInt(p.a,10):NaN;
      var upH=!isNaN(nh)&&!isNaN(ph)&&nh>ph,upA=!isNaN(na)&&!isNaN(pa)&&na>pa;
      if(p&&(upH||upA)){
        var side=upH?"h":"a";
        var hn=k.split("|")[0],an=k.split("|")[1];
        goal(r,side);
        if(alerts[k])notify((side==="h"?hn+" "+h+" - "+a+" "+an:an+" "+a+" - "+h+" "+hn));
      }
      prev[k]={h:h,a:a};
    });
  }
  function tick(){
    var now=Date.now();
    rows().forEach(function(r){
      var c=r.querySelector(".ks-cd");if(!c)return;
      var d=Number(r.dataset.d)-now;
      if(!(d>0)){c.textContent="";return}
      var m=Math.floor(d/60000),s=Math.floor(d/1000)%60;
      c.textContent="باقي "+D8(m)+":"+(s<10?"٠":"")+D8(s);
    });
  }
  function decorate(){
    rows().forEach(function(r){
      if(!r.dataset.ksb){
        r.dataset.ksb="1";
        var b=document.createElement("button");
        b.type="button";b.className="ks-bell"+(alerts[r.dataset.k]?" on":"");b.textContent="🔔";
        b.setAttribute("aria-label","تنبيه لما النتيجة تتغير");
        b.addEventListener("click",function(ev){
          ev.preventDefault();ev.stopPropagation();
          var k=r.dataset.k;
          if(alerts[k]){delete alerts[k];b.classList.remove("on");save();return}
          if("Notification" in window&&Notification.permission==="default"){
            Notification.requestPermission().then(function(p){if(p==="granted"){alerts[k]=1;b.classList.add("on");save()}});
            return;
          }
          alerts[k]=1;b.classList.add("on");save();
          if("Notification" in window&&Notification.permission==="denied")b.title="الإشعارات مقفولة من إعدادات المتصفح — التنبيه هيظهر جوه الصفحة بس";
        });
        r.appendChild(b);
      }
      if(r.dataset.st==="upcoming"&&r.dataset.d&&!r.querySelector(".ks-cd")){
        var ce=r.querySelector(".center");
        if(ce){var c=document.createElement("span");c.className="ks-cd";ce.appendChild(c)}
      }
    });
    tick();
  }
  var t=null;
  function boot(){decorate();check();
    var host=document.getElementById("leagueBlocks");
    if(host&&window.MutationObserver){new MutationObserver(function(){clearTimeout(t);t=setTimeout(decorate,120)}).observe(host,{childList:true,subtree:true})}
  }
  if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",boot);else boot();
  setInterval(function(){if(document.hidden)return;tick()},1000);
  setInterval(function(){if(document.hidden)return;check()},20000);
  var q=new URLSearchParams(location.search);
  if(q.get("cd")){
    var secs=parseInt(q.get("cd"),10)||90;
    setTimeout(function(){var r=rows()[0];if(!r)return;r.dataset.st="upcoming";r.dataset.d=String(Date.now()+secs*1000);
      if(!r.querySelector(".ks-cd")){var ce=r.querySelector(".center");if(ce){var c=document.createElement("span");c.className="ks-cd";ce.appendChild(c)}}
      tick();},1500);
  }
  if(q.get("goaltest")){
    var side=q.get("goaltest")==="away"?"a":"h";
    setTimeout(function(){var r=rows()[0];if(!r)return;goal(r,side);
      if(alerts[r.dataset.k])notify("تجربة: هدف "+(side==="h"?r.dataset.k.split("|")[0]:r.dataset.k.split("|")[1]));},2500);
  }
})();

